  "summary": "The code contains critical vulnerabilities including path traversal and memory exhaustion risks due to synchronous, unbounded file reads. Overall health is poor; the implementation requires refactoring to use asynchronous streaming, secure path sanitization, and environment-based configuration.",
  "fixed_code": "import os\nimport aiofiles\nfrom typing import Any\nfrom fastapi import FastAPI, File, HTTPException, UploadFile\n\napp = FastAPI()\nUPLOAD_DIR = os.getenv('UPLOAD_DIR', '/var/app/uploads')\nMAX_BYTES = 5 * 1024 * 1024\nALLOWED_TYPES = {\"image/png\", \"image/jpeg\"}\n\n@app.post(\"/avatars\")\nasync def upload_avatar(file: UploadFile = File(...)) -> dict[str, Any]:\n    \"\"\"Uploads an avatar image, validating size and content type.\"\"\"\n    if file.content_type not in ALLOWED_TYPES:\n        raise HTTPException(status_code=415, detail=\"unsupported type\")\n    \n    filename = os.path.basename(file.filename)\n    dest = os.path.join(UPLOAD_DIR, filename)\n    \n    size = 0\n    async with aiofiles.open(dest, \"wb\") as fh:\n        while chunk := await file.read(1024 * 1024):\n            size += len(chunk)\n            if size > MAX_BYTES:\n                raise HTTPException(status_code=413, detail=\"file too large\")\n            await fh.write(chunk)\n            \n    return {\"stored_as\": filename, \"bytes\": size}"
}
